type APIPublicTestSuite struct {
	suite.Suite

	api *servertest.Harness
}

func (s *APIPublicTestSuite) SetupSuite() {
	s.api = servertest.New(s.T(), "internal/behaviors/log/source/gen/api.yaml", gen.Routes)
}

func (s *APIPublicTestSuite) TestRoutes() {
	routes := gen.Routes(server.New(slog.Default(), nil, nil, dispatch.Deps{}))
	want := []struct {
		method     string
		path       string
		permission string
	}{
		{
			method:     http.MethodGet,
			path:       "/api/node/:hostname/log/source",
			permission: "log:read",
		},
	}

	s.Require().Len(routes, len(want))
	for i, w := range want {
		s.Run(w.method+" "+w.path, func() {
			s.Equal(w.method, routes[i].Method)
			s.Equal(w.path, routes[i].Path)
			s.Equal(w.permission, routes[i].Permission)
			s.NotNil(routes[i].Handler)
		})
	}
}

func TestAPIPublicTestSuite(
	t *testing.T,
) {
	suite.Run(t, new(APIPublicTestSuite))
}

// TestList sends GET /api/node/{hostname}/log/source and checks each answer's
// response.
func (s *APIPublicTestSuite) TestList() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the example \"The sources\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"source.list",
				source.ListInput{},
				servertest.Completed("server1", `[{"name":"cron"},{"name":"nginx"},{"name":"sshd"}]`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","name":"cron","status":"ok"},{"hostname":"server1","name":"nginx","status":"ok"},{"hostname":"server1","name":"sshd","status":"ok"}]}`,
		},
		{
			Name: "when the example \"The sources\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"source.list",
				source.ListInput{},
				servertest.Completed("server1", `[{"name":"cron"},{"name":"nginx"},{"name":"sshd"}]`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"hostname":"server1","name":"cron","status":"ok"},{"hostname":"server1","name":"nginx","status":"ok"},{"hostname":"server1","name":"sshd","status":"ok"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the host skips it, its row says skipped",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"source.list",
				source.ListInput{},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
		{
			Name: "when the host fails it, its row says failed",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"source.list",
				source.ListInput{},
				servertest.Failed("server1", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"boom","hostname":"server1","status":"failed"}]}`,
		},
		{
			Name: "when the host never answers, its row says timeout",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"source.list",
				source.ListInput{},
				servertest.TimedOut("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"","hostname":"server1","status":"timeout"}]}`,
		},
		{
			Name: "when the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/server1/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"server1",
				"source.list",
				source.ListInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when broadcast and the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/_all/log/source",
			},
			Token: servertest.Read,
			Job: servertest.Query(
				"_all",
				"source.list",
				source.ListInput{},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
	})
}

// TestListValidationHTTP sends requests the API refuses before any job is
// queued.
func (s *APIPublicTestSuite) TestListValidationHTTP() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the target is not an agent, it is a 400",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node/nowhere/log/source",
			},
			Token:    servertest.Read,
			WantCode: http.StatusBadRequest,
		},
		{
			Name: "when the target is empty, it is a 400",
			Request: servertest.Request{
				Method: http.MethodGet,
				Path:   "/api/node//log/source",
			},
			Token:    servertest.Read,
			WantCode: http.StatusBadRequest,
		},
	})
}

